#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/../.."
mkdir -p build/core-tests
javac -d build/core-tests android-tv-launcher/app/src/main/java/local/tv/home/{Playlist,Network,ProviderUrls,ProviderFileRanges,VideoFiles,EpisodeOrder,SourceRanking,SourceWindow,StreamRate,ChannelQuery,EpgMatch,EpgLookup,SkyNumbers,GuideOrder,SkipQueue,ErrorLog,SpeedTest,ChannelIdentity,ChannelCategory,ProviderFailure,LiveProgress,VodSourceFailover,LiveBuffering,LiveRestartBudget,ColourPress,VideoDetails,ProviderOutage,LiveRacePlan,LiveSourceDeadline,QualityClaims,LiveStallRules,LiveUpgradePlan,ContinueWatching,SubtitleStyle,TitleRatings,PlaybackEnd}.java android-tv-launcher/tests/{PlaylistTest,NetworkTest,ProviderFileRangesTest,VideoFilesTest,SourceWindowTest,StreamRateTest,ChannelQueryTest,EpgMatchTest,EpgLookupTest,SkyNumbersTest,GuideOrderTest,SkipQueueTest,TroubleshootingTest,ChannelIdentityTest,ProviderFailureTest,LiveProgressTest,VodSourceFailoverTest,LiveBufferingTest,LiveRestartBudgetTest,ColourPressTest,VideoDetailsTest,ProviderOutageTest,LiveRacePlanTest,LiveSourceDeadlineTest,QualityClaimsTest,LiveStallRulesTest,LiveUpgradePlanTest,ContinueWatchingTest,SubtitleStyleTest,TitleRatingsTest,PlaybackEndTest}.java
for test in PlaylistTest NetworkTest ProviderFileRangesTest VideoFilesTest SourceWindowTest StreamRateTest ChannelQueryTest EpgMatchTest EpgLookupTest SkyNumbersTest GuideOrderTest SkipQueueTest TroubleshootingTest ChannelIdentityTest ProviderFailureTest LiveProgressTest VodSourceFailoverTest LiveBufferingTest LiveRestartBudgetTest ColourPressTest VideoDetailsTest ProviderOutageTest LiveRacePlanTest LiveSourceDeadlineTest QualityClaimsTest LiveStallRulesTest LiveUpgradePlanTest ContinueWatchingTest SubtitleStyleTest TitleRatingsTest PlaybackEndTest; do
    java -Xmx64m -cp build/core-tests local.tv.home.$test
done
